// ParserGrammarData is the embedded default Haskell parser grammar (Haskell 2010).
// Version-aware callers use VersionedParserGrammars instead.
var ParserGrammarData = parserGrammarV2010

// VersionedParserGrammars maps a Haskell version string to its embedded parser
// grammar. The loader looks the grammar up here with no file I/O.
var VersionedParserGrammars = map[string]*gt.ParserGrammar{
	`1.0`:  parserGrammarV1_0,
	`1.1`:  parserGrammarV1_1,
	`1.2`:  parserGrammarV1_2,
	`1.3`:  parserGrammarV1_3,
	`1.4`:  parserGrammarV1_4,
	`98`:   parserGrammarV98,
	`2010`: parserGrammarV2010,
}
